46:     public static int waitForExitProcess(Pointer hProcess) throws InterruptedException {
47:         while (true) {
48:             if (Thread.interrupted())
49:                 throw new InterruptedException();
50: 
51:             Kernel32.INSTANCE.WaitForSingleObject(hProcess, 1000);
52:             IntByReference exitCode = new IntByReference();
53:             exitCode.setValue(-1);
54:             Kernel32.INSTANCE.GetExitCodeProcess(hProcess, exitCode);
55: 
56:             int v = exitCode.getValue();
57:             if (v != Kernel32.STILL_ACTIVE) {
58:                 return v;
59:             }
60:         }
61:     }
