72:         String canonicalPath = file.getCanonicalPath();
73:         String path;
74:         if (canonicalPath.length() < 260) {
75:             // path is short, use as-is
76:             path = canonicalPath;
77:         } else if (canonicalPath.startsWith("\\\\")) {
78:             // network share
79:             // \\server\share --> \\?\UNC\server\share
80:             path = "\\\\?\\UNC\\" + canonicalPath.substring(2);
81:         } else {
82:             // prefix, canonical path should be normalized and absolute so this should work.
83:             path = "\\\\?\\" + canonicalPath;
